//! PDF417 encoder (ISO/IEC 15438). Every rule here is pinned against
//! zint renders — see docs/STATUS.md pdf417 blocks and the truth battery
//! (testdata/zint_truth.txt, regenerated by tools/pdf417_truth.py).
//!
//! Pipeline: high-level encode the payload into data codewords (Text /
//! Byte / Numeric compaction with zint's observed switching rules), pick
//! the symbol geometry, append pad + ECC codewords, then paint row
//! bands: start pattern, left row indicator, data cells, right row
//! indicator, stop pattern.
//!
//! Empirical contracts (all zint-verified):
//! - stream = [descriptor][data][pads(900)][ecc] laid row-major over the
//!   data cells; descriptor = rows*cols - k = 1 + #data + #pads.
//! - ECC = rs_encode(GF(929), [desc + data + pads], k), k = 2^(level+1);
//!   zint's default level is 2.
//! - geometry: the smallest column count c with ceil(S_min / c) <= 3c+4
//!   (S_min = 1 + #data + k), rows = ceil(S_min / c); row band height =
//!   max(3, 50/rows) modules.
//! - numeric: leading '1' + digits, base 900 big-endian, ONE group for
//!   the whole run (zint does not split at 44 digits); latch 902, and a
//!   900 back-latch when text follows. A digit run switches to NC when
//!   that yields a strictly shorter encoding, or on a tie with >= 7
//!   digits.
//! - byte: the segment spans the first .. last non-TC byte; a single
//!   trailing payload byte is absorbed into it; 1-byte segments use the
//!   913 shift (+900 when text follows), otherwise 924 (count % 6 == 0)
//!   or 901 with the 1-5 tail bytes as raw codewords.
//! - text: sub-mode machine mirroring text.rs (Alpha/Lower/Mixed/Punct,
//!   As/Ps one-shot shifts, latch routes), pad sub-value 29 on odd
//!   tails; mode switches pad the pair with 29.

use crate::rs::rs_encode;
use crate::stream::{START, STOP};
use crate::tables::{cluster_of_row, CLUSTER_0, CLUSTER_3, CLUSTER_6};
use crate::text_tables::{Cell, ALPHA, LOWER, MIXED, PUNCT, TEXT_TABLES};

pub const DEFAULT_LEVEL: u8 = 2;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EncodeError {
    /// No legal geometry (rows <= 90, cols <= 30, descriptor <= 928).
    PayloadTooLarge,
}

// ---------------------------------------------------------------------------
// Text compaction: char -> sub-value machinery (mirror of text.rs)
// ---------------------------------------------------------------------------

/// Direct sub-value for `ch` in `sub`, if the sub-mode carries it.
fn direct(sub: usize, ch: u8) -> Option<u8> {
    TEXT_TABLES[sub]
        .iter()
        .position(|c| matches!(c, Cell::Ch(x) if *x == ch))
        .map(|i| i as u8)
}

fn tc_able(ch: u8) -> bool {
    (0..4).any(|s| direct(s, ch).is_some())
}

/// One-shot shift sub-value entering `target` from `sub`, if any
/// (spec Table 3: As from Lower only — Mixed has no As cell, its 27
/// is Ll; P/S from Alpha/Lower/Mixed).
fn shift_of(sub: usize, target: usize) -> Option<u8> {
    match (sub, target) {
        (LOWER, ALPHA) => Some(27),                                   // As
        (ALPHA, PUNCT) | (LOWER, PUNCT) | (MIXED, PUNCT) => Some(29), // Ps
        _ => None,
    }
}

/// Latch code `from` -> `to` (spec Table 3 switch cells).
fn latch(from: usize, to: usize) -> Option<u8> {
    match (from, to) {
        (ALPHA, LOWER) => Some(27), // Ll
        (ALPHA, MIXED) => Some(28), // Ml
        (LOWER, MIXED) => Some(28), // Ml
        (MIXED, PUNCT) => Some(25), // Pl
        (MIXED, LOWER) => Some(27), // Ll
        (MIXED, ALPHA) => Some(28), // Al
        (PUNCT, ALPHA) => Some(29), // Al
        _ => None,
    }
}

/// Shortest latch path `from` -> `to` as sub-values (<= 2 hops).
fn latch_path(from: usize, to: usize) -> Vec<u8> {
    if let Some(c) = latch(from, to) {
        return vec![c];
    }
    for mid in 0..4 {
        if let (Some(a), Some(b)) = (latch(from, mid), latch(mid, to)) {
            return vec![a, b];
        }
    }
    unreachable!("all sub-mode pairs are latch-reachable within two hops");
}

/// Consecutive bytes from `i` with a direct code in `sub`.
fn run_len(text: &[u8], i: usize, sub: usize) -> usize {
    text[i..]
        .iter()
        .take_while(|&&b| direct(sub, b).is_some())
        .count()
}

/// Append the sub-values for the TC-able stretch starting at `i`
/// (stops at the first non-TC byte, or a digit run the `nc_stop`
/// predicate flags as an NC candidate the caller will decide — runs
/// already declared TC via `tc_decided` are consumed in TC); returns
/// the new position. `sub` tracks the current sub-mode.
fn tc_push_subs(
    text: &[u8],
    mut i: usize,
    subs: &mut Vec<u8>,
    sub: &mut usize,
    nc_stop: &dyn Fn(usize, usize) -> bool,
    tc_decided: &mut std::collections::HashSet<usize>,
) -> usize {
    while i < text.len() && tc_able(text[i]) {
        if text[i].is_ascii_digit() {
            let n = text[i..]
                .iter()
                .take_while(|&&b| b.is_ascii_digit())
                .count();
            if n >= 5 && !tc_decided.contains(&i) && nc_stop(i, n) {
                break; // NC candidate: let the caller decide
            }
        }
        let ch = text[i];
        if let Some(v) = direct(*sub, ch) {
            subs.push(v);
            i += 1;
            continue;
        }
        // Candidate target sub-modes with their direct-run lengths.
        let mut targets: Vec<(usize, usize)> = (0..4)
            .filter(|&t| t != *sub)
            .map(|t| (t, run_len(text, i, t)))
            .filter(|&(_, r)| r > 0)
            .collect();
        targets.sort_by_key(|&(_, r)| std::cmp::Reverse(r));
        if targets.is_empty() {
            unreachable!("char is TC-able so some sub carries it");
        }
        // A single out-of-sub char rides a one-shot shift when that is
        // STRICTLY cheaper than latching (zint-verified: the url '.' and
        // '/' shift via P/S; auto_long's 'F' before an NC run latches —
        // shift == latch there and the latch wins). The latch cost is
        // the route + the char + the eventual return to `sub` (1 sub
        // when the next char is direct back here and not an NC-candidate
        // digit run).
        if targets[0].1 == 1 {
            if let Some(&(t, _)) = targets.iter().find(|&&(t, _)| shift_of(*sub, t).is_some()) {
                let exit = text
                    .get(i + 1)
                    .map(|&nx| {
                        tc_able(nx)
                            && direct(*sub, nx).is_some()
                            && !(nx.is_ascii_digit()
                                && text[i + 1..]
                                    .iter()
                                    .take_while(|&&b| b.is_ascii_digit())
                                    .count()
                                    >= 5)
                    })
                    .unwrap_or(false) as usize;
                let latch_cost = latch_path(*sub, t).len() + 1 + exit;
                if 2 < latch_cost {
                    subs.push(shift_of(*sub, t).unwrap());
                    subs.push(direct(t, ch).unwrap());
                    i += 1;
                    continue;
                }
            }
        }
        let target = targets[0].0;
        for c in latch_path(*sub, target) {
            subs.push(c);
        }
        *sub = target;
    }
    i
}

// ---------------------------------------------------------------------------
// Numeric compaction: leading '1' + digits, base 900 big-endian
// ---------------------------------------------------------------------------

fn nc_groups(digits: &[u8]) -> Vec<u16> {
    // zint splits the run into 44-digit chunks (the spec's recommended
    // group size), each with its own leading '1' — verified by stream
    // VALUES at 45/90 digits, where the one-group form has the same
    // codeword count but different values (docs/STATUS.md).
    let mut out = Vec::new();
    for chunk in digits.chunks(44) {
        out.extend(nc_group(chunk));
    }
    out
}

/// One numeric group: value = "1" + digits as a big decimal, emitted
/// base-900 big-endian.
fn nc_group(digits: &[u8]) -> Vec<u16> {
    // value = "1" + digits as a big decimal; emit base-900 big-endian.
    let mut dec: Vec<u8> = vec![1]; // decimal digits, most significant first
    for &d in digits {
        let mut carry = d as u32; // dec = dec * 10 + d
        for x in dec.iter_mut().rev() {
            let v = *x as u32 * 10 + carry;
            *x = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            dec.insert(0, carry as u8);
            carry = 0;
        }
    }
    let mut out = Vec::new();
    while dec.iter().any(|&x| x != 0) {
        let mut rem = 0u32;
        let mut next = Vec::with_capacity(dec.len());
        for &x in &dec {
            let v = rem * 10 + x as u32;
            if !next.is_empty() || v / 900 > 0 {
                next.push((v / 900) as u8);
            }
            rem = v % 900;
        }
        out.insert(0, rem as u16);
        dec = next;
    }
    if out.is_empty() {
        out.push(0);
    }
    out
}

// ---------------------------------------------------------------------------
// High-level encoding
// ---------------------------------------------------------------------------

/// Encode the payload into data codewords (no descriptor/pads/ecc).
/// The numeric-compaction decision for a digit run, fitted against the
/// zint oracle over a shape zoo (tools session notes, docs/STATUS.md).
/// Thresholds are min run lengths for latching NC; the context is the
/// run's own edges: `whole` = the run is the entire payload (zint
/// always latches NC there, even where TC would be shorter), the
/// `*_byte` flags say whether a Byte-Compaction segment sits directly
/// before/after the run. Runs strictly between two byte segments are
/// swallowed by the byte-span builder and never decided here.
fn run_wants_nc(text: &[u8], i: usize, n: usize) -> bool {
    let end = i + n;
    let at_start = i == 0;
    let at_end = end == text.len();
    let prev_byte = !at_start && !tc_able(text[i - 1]);
    let next_byte = !at_end && !tc_able(text[end]);
    if at_start && at_end {
        return true; // whole-payload digits: zint always latches NC
    }
    if prev_byte {
        // a 1-digit run at the very end joins the preceding segment
        return if at_end { n >= 2 } else { n >= 4 };
    }
    if at_start {
        return if next_byte { n >= 2 } else { n >= 8 };
    }
    if next_byte {
        return n >= 5; // (text, byte)
    }
    if at_end {
        return n >= 7; // (text, end)
    }
    n >= 8 // (text, text)
}

/// Encode the payload into data codewords (no descriptor/pads/ecc).
pub fn high_level(text: &[u8]) -> Vec<u16> {
    let mut out: Vec<u16> = Vec::new();
    let mut subs: Vec<u8> = Vec::new(); // pending TC sub-values
    let mut sub = ALPHA;
    let mut tc_decided = std::collections::HashSet::new();
    // a lone leading digit zint pulls into the following byte segment
    // ('1é' -> [901, 49, 195, 169], no TC at all)
    let mut lead_digit: Option<u8> = None;
    let mut i = 0;
    while i < text.len() {
        // Numeric: a digit run, decided by the zint-fitted threshold
        // table (see `run_wants_nc`).
        if text[i].is_ascii_digit() {
            let n = text[i..]
                .iter()
                .take_while(|&&b| b.is_ascii_digit())
                .count();
            let end = i + n;
            // a single digit straight into a byte segment joins it
            if n == 1 && i == 0 && end < text.len() && !tc_able(text[end]) {
                lead_digit = Some(text[i]);
                i += 1;
                continue;
            }
            if run_wants_nc(text, i, n) {
                flush_tc(&mut out, &mut subs);
                out.push(902);
                let digits: Vec<u8> = text[i..end].iter().map(|b| b - b'0').collect();
                out.extend(nc_groups(&digits));
                // latch back to Text only when Text content follows; a
                // following byte/numeric segment re-latches on its own
                if end < text.len() && tc_able(text[end]) {
                    out.push(900);
                    sub = ALPHA;
                }
                i = end;
                continue;
            }
            if n >= 5 {
                tc_decided.insert(i); // decided TC: the push may consume it
            }
        }
        // Byte: the segment spans the first .. last non-TC byte.
        if !tc_able(text[i]) {
            let mut last = i;
            for (k, b) in text.iter().enumerate() {
                if !tc_able(*b) {
                    last = k;
                }
            }
            let mut end = last + 1;
            if end == text.len() - 1 {
                end = text.len(); // absorb a single trailing payload byte
            }
            let n = end - i + usize::from(lead_digit.is_some());
            flush_tc(&mut out, &mut subs);
            // the byte list: an optional lead digit pulled in from the
            // payload start, then the span text[i..end]
            let byte_at = |k: usize| -> u8 {
                match lead_digit {
                    Some(d) if k == 0 => d,
                    Some(_) => text[i + k - 1],
                    None => text[i + k],
                }
            };
            if n == 1 {
                out.push(913);
                out.push(byte_at(0) as u16);
            } else {
                out.push(if n % 6 == 0 { 924 } else { 901 });
                let full = (n - n % 6) / 6;
                let tail = n % 6;
                for g in 0..full {
                    let group: Vec<u8> = (0..6).map(|k| byte_at(g * 6 + k)).collect();
                    let v: u64 = group.iter().fold(0u64, |a, &b| (a << 8) | b as u64);
                    for sh in (0..5).rev() {
                        out.push(((v / 900u64.pow(sh)) % 900) as u16);
                    }
                }
                for k in 0..tail {
                    out.push(byte_at(n - tail + k) as u16);
                }
            }
            if end < text.len() {
                let next_is_text = if text[end].is_ascii_digit() {
                    let rn = text[end..]
                        .iter()
                        .take_while(|&&b| b.is_ascii_digit())
                        .count();
                    !run_wants_nc(text, end, rn)
                } else {
                    true
                };
                if next_is_text {
                    out.push(900);
                    sub = ALPHA;
                }
            }
            lead_digit = None;
            i = end;
            continue;
        }
        i = tc_push_subs(
            text,
            i,
            &mut subs,
            &mut sub,
            &|_p, _n| true,
            &mut tc_decided,
        );
    }
    flush_tc(&mut out, &mut subs);
    out
}

/// Flush pending sub-values as codeword pairs, padding with 29.
fn flush_tc(out: &mut Vec<u16>, subs: &mut Vec<u8>) {
    if subs.len() % 2 == 1 {
        subs.push(29);
    }
    for p in subs.chunks(2) {
        out.push(p[0] as u16 * 30 + p[1] as u16);
    }
    subs.clear();
}

/// Encoded symbol: module matrix (1 = dark, no quiet zone) plus the
/// exact pixel dimensions.
pub struct Symbol {
    pub matrix: Vec<u8>,
    pub width: usize,
    pub height: usize,
    pub rows: usize,
    pub cols: usize,
}

/// Encode into a symbol matrix (1 = dark), no quiet zone.
pub fn encode(text: &[u8]) -> Result<Vec<u8>, EncodeError> {
    encode_with(text, DEFAULT_LEVEL)
}

pub fn encode_with(text: &[u8], level: u8) -> Result<Vec<u8>, EncodeError> {
    encode_full(text, level).map(|s| s.matrix)
}

pub fn encode_full(text: &[u8], level: u8) -> Result<Symbol, EncodeError> {
    encode_full_opts(text, level, 0)
}

/// `cols_override`: 0 = auto, else the exact data-column count.
pub fn encode_full_opts(text: &[u8], level: u8, cols_override: u8) -> Result<Symbol, EncodeError> {
    let data = high_level(text);
    assemble(data, &[], level, cols_override)
}

/// Macro PDF417 (Annex H) optional/mandatory control-block fields.
/// `file_id` is raw codewords 0..=899 (transmitted as their 3-digit
/// ASCII); `segment_index` 0..=99998 (position within the file);
/// `last` appends the 922 terminator. Optional fields appear at most
/// once per file and identically in every segment that carries them.
pub struct MacroFields<'a> {
    pub segment_index: u32,
    pub file_id: &'a [u16],
    pub last: bool,
    pub file_name: Option<&'a str>,
    pub sender: Option<&'a str>,
    pub addressee: Option<&'a str>,
    pub segment_count: Option<u32>,
    pub timestamp: Option<u64>,
    pub file_size: Option<u64>,
    pub checksum: Option<u16>,
}

/// "Add the digit 1 to the most significant position" over a fixed
/// `digits`-wide zero-padded value, then base-900 (index/count use 5
/// digits -> 2 codewords; timestamp 10 -> 4; checksum 5 -> 2).
fn nc_fixed(value: u64, digits: usize) -> Vec<u16> {
    let s = format!("1{:0width$}", value, width = digits);
    let mut v = 0u64;
    for b in s.bytes() {
        v = v * 10 + (b - b'0') as u64;
    }
    let mut out = Vec::new();
    let mut sh = ((s.len() - 1) / 3) as u32; // codewords = INT(n/3)+1
    loop {
        let p = 900u64.pow(sh);
        out.push((v / p % 900) as u16);
        if sh == 0 {
            break;
        }
        sh -= 1;
    }
    out
}

/// Implied-Alpha Text Compaction for a Control Block field (H.3: each
/// field starts in TC/Alpha implicitly, H.4 shows the direct form):
/// pure lowercase/space strings of even length pack straight into
/// base-30 pairs with no latches — "cen be" -> [64][416][34]. Anything
/// else falls back to the full high-level encoder, whose explicit
/// latches are legal inside a TC field.
fn tc_field(s: &str) -> Vec<u16> {
    let val = |c: u8| if c == b' ' { 26u16 } else { (c - b'a') as u16 };
    let direct =
        !s.is_empty() && s.len() % 2 == 0 && s.bytes().all(|b| b.is_ascii_lowercase() || b == b' ');
    if direct {
        s.as_bytes()
            .chunks(2)
            .map(|p| val(p[0]) * 30 + val(p[1]))
            .collect()
    } else {
        high_level(s.as_bytes())
    }
}

/// The Macro PDF417 Control Block codewords: [928] [index 2] [file id]
/// ([923] [designator] [field data])* [922 if last]. Field data starts
/// in the field's implied default mode (TC fields from Alpha; NC
/// fields need no latch), so no mode codewords are emitted here.
fn control_block(m: &MacroFields) -> Vec<u16> {
    let mut out = vec![928];
    out.extend(nc_fixed(m.segment_index as u64, 5));
    out.extend_from_slice(m.file_id);
    if let Some(name) = m.file_name {
        out.extend_from_slice(&[923, 0]);
        out.extend(high_level(name.as_bytes())); // TC, implied Alpha reset
    }
    if let Some(count) = m.segment_count {
        out.extend_from_slice(&[923, 1]);
        out.extend(nc_fixed(count as u64, 5));
    }
    if let Some(ts) = m.timestamp {
        out.extend_from_slice(&[923, 2]);
        out.extend(nc_fixed(ts, 10));
    }
    // Annex H.4: sender/addressee are Text Compaction fields (designators
    // 3/4), starting in implied Alpha — "cen be" -> [64][416][34].
    // file_name keeps high_level (explicit latches) for byte parity with
    // Okapi's macro encoder.
    if let Some(sender) = m.sender {
        out.extend_from_slice(&[923, 3]);
        out.extend(tc_field(sender));
    }
    if let Some(rcpt) = m.addressee {
        out.extend_from_slice(&[923, 4]);
        out.extend(tc_field(rcpt));
    }
    if let Some(size) = m.file_size {
        out.extend_from_slice(&[923, 5]);
        let digits: Vec<u8> = size.to_string().bytes().map(|b| b - b'0').collect();
        out.extend(nc_groups(&digits));
    }
    if let Some(crc) = m.checksum {
        out.extend_from_slice(&[923, 6]);
        out.extend(nc_fixed(crc as u64, 5));
    }
    if m.last {
        out.push(922);
    }
    out
}

/// Encode one segment of a Macro PDF417 distributed file. The payload
/// is high-level encoded as usual; the control block follows the data
/// and is counted in the Symbol Length Descriptor (Annex H.2). Pad
/// codewords sit between the data and the block (okapi's layout, read
/// by every decoder): 900 is a no-op latch there, while pads after the
/// block would be swallowed into the last variable-length field.
pub fn encode_macro_full(
    m: &MacroFields,
    payload: &[u8],
    level: u8,
) -> Result<Symbol, EncodeError> {
    let data = high_level(payload);
    let cb = control_block(m);
    assemble(data, &cb, level, 0)
}

/// Geometry + pads + descriptor + ECC + paint. `tail` codewords (a
/// Macro control block, if any) are laid after the pads.
fn assemble(
    data: Vec<u16>,
    tail: &[u16],
    level: u8,
    cols_override: u8,
) -> Result<Symbol, EncodeError> {
    let k = crate::rs::k_for_level(level);
    let s_min = 1 + data.len() + tail.len() + k;
    let mut geo = None;
    let cols_range: Vec<usize> = if cols_override == 0 {
        (1..=30usize).collect()
    } else {
        vec![cols_override as usize]
    };
    for cols in cols_range {
        let rows = s_min.div_ceil(cols);
        if rows > 90 {
            continue;
        }
        if rows * cols - k > 928 {
            continue; // descriptor cap
        }
        if rows <= 3 * cols + 4 || cols_override != 0 {
            geo = Some((rows, cols));
            break;
        }
    }
    let Some((rows, cols)) = geo else {
        return Err(EncodeError::PayloadTooLarge);
    };
    let pads = rows * cols - s_min;
    let desc = (rows * cols - k) as u16;

    let mut msg = Vec::with_capacity(rows * cols);
    msg.push(desc);
    msg.extend_from_slice(&data);
    msg.extend(std::iter::repeat_n(900u16, pads));
    msg.extend_from_slice(tail);
    let ecc = rs_encode(&msg, k);
    msg.extend_from_slice(&ecc);
    debug_assert_eq!(msg.len(), rows * cols);

    Ok(Symbol {
        width: 69 + 17 * cols,
        height: rows * band_height(rows),
        rows,
        cols,
        matrix: paint(rows, cols, &msg, level),
    })
}

/// Row band height in modules (zint scales the total height to ~50).
fn band_height(rows: usize) -> usize {
    (50 / rows).max(3)
}

/// Paint the module matrix for a complete codeword `stream`.
fn paint(rows: usize, cols: usize, stream: &[u16], level: u8) -> Vec<u8> {
    let band = band_height(rows);
    let w = 69 + 17 * cols;
    let h = rows * band;
    let mut m = vec![0u8; w * h]; // 1 = dark
    let mut runs: Vec<u8> = Vec::with_capacity(16);

    for r in 0..rows {
        let cluster = cluster_of_row(r + 1);
        let table: &[[u8; 8]; 929] = match cluster {
            0 => &CLUSTER_0,
            3 => &CLUSTER_3,
            _ => &CLUSTER_6,
        };
        // Row indicator values (spec 2.2.3, lib.rs spec example).
        let x = r / 3; // (row-1)/3 for 1-based rows
        let y = (rows - 1) / 3;
        let z = level as usize * 3 + (rows - 1) % 3;
        let v = cols - 1;
        let (l, rr) = match cluster {
            0 => (30 * x + y, 30 * x + v),
            3 => (30 * x + z, 30 * x + y),
            _ => (30 * x + v, 30 * x + z),
        };

        runs.clear();
        runs.extend_from_slice(&START);
        runs.extend_from_slice(&table[l as usize]);
        for c in 0..cols {
            runs.extend_from_slice(&table[stream[r * cols + c] as usize]);
        }
        runs.extend_from_slice(&table[rr as usize]);
        runs.extend_from_slice(&STOP);

        let mut x = 0usize;
        let mut dark = true;
        for &len in &runs {
            for dx in 0..len as usize {
                for dy in 0..band {
                    m[(r * band + dy) * w + x + dx] = dark as u8;
                }
            }
            x += len as usize;
            dark = !dark;
        }
        debug_assert_eq!(x, w);
    }
    m
}

/// The 8-element pattern for `value` in `cluster`.
pub fn pattern_of(cluster: usize, value: u16) -> &'static [u8; 8] {
    match cluster {
        0 => &CLUSTER_0[value as usize],
        3 => &CLUSTER_3[value as usize],
        _ => &CLUSTER_6[value as usize],
    }
}
